source('tests/helper.R');source_test_runtime()
root<-normalizePath('.',winslash='/');tmp<-tempfile('canonical-vitals-');dir.create(tmp);out<-file.path(tmp,'site')
profile<-function(table,field,...)modifyList(list(table_name=table,column_name=field,column_type='decimal',column_class='numeric',profile_kind='numeric',n_rows=100,n_available=80,pct_available=80,n_missing=20,n_distinct_capped=20,min=0,max=999,mean=24,median=23,p25=21,p75=26,is_sensitive=FALSE,availability_privacy_status='available'),list(...))
publish<-function(rows,payload=list(run_id='SYNTHETIC_VITALS')){table<-Filter(function(t)t$id=='column_profiles',atlas_output_evidence(NULL,root,list()))[[1]];table$rows<-rows;atlas_write_site_bundle(out,payload,list(table),root,'legacy_payload')}
events<-lapply(c('displayname','numericvalue','recorded_time','meas_value','meas_value_clean','val_type_c','val_type_name','isaccepted_yn','template_name','date_received','datetime_created'),function(f)profile('SP_VitaleVaerdier',f))
dedicated<-list(profile('SP_PatientInfo','bmi'),profile('SP_PatientInfo','weight_in_kg'),profile('SP_PatientInfo','height_in_cm'),profile('RKKP_DaMyDa','Reg_Hoejde'),profile('RKKP_DaMyDa','Reg_Vaegt'))
rows<-c(events,dedicated,list(dedicated[[1]],profile('SP_VitaleVaerdier_old','numericvalue'),profile('sp_vitalevaerdier','numericvalue'),profile('SP_VitaleVaerdier','NumericValue'),profile('SP_VitaleVaerdier','patient_id'),profile('Other','bmi')))
paths<-publish(rows,list(column_profile_rows=list(profile('SP_PatientInfo','bmi',mean=999))))
emitted<-read_public_table(out,'column_profiles')
expect_equal(lapply(emitted,function(r)r[c('table_name','column_name')]),lapply(rows,function(r)r[c('table_name','column_name')]))
expect_equal(emitted[[12]],emitted[[17]]);expect_true(all(vapply(emitted,function(r)is.null(r$mean),logical(1))))
expect_equal(emitted[[12]]$numeric_privacy_status,'needs_verified_grouped_evidence');expect_equal(emitted[[12]]$n_available,80L)
wire<-jsonlite::fromJSON(paths$payload_json,simplifyVector=FALSE);expect_true(is.null(wire$payload$column_profile_rows));expect_equal(wire$payload$export_contract,'dalycare-lazy-v1')
unsafe<-list(raw_value='FORBIDDEN_RAW',top_value='FORBIDDEN_TOP',patient_id='FORBIDDEN_ID',arbitrary='FORBIDDEN_METADATA',min_date='1927-02-03',max_date='1927-02-04')
invisible(publish(list(modifyList(profile('SP_VitaleVaerdier','numericvalue'),unsafe),modifyList(profile('SP_PatientInfo','bmi'),unsafe))))
for(path in list.files(out,recursive=TRUE,full.names=TRUE))expect_false(any(grepl('FORBIDDEN|1927-',readLines(path,warn=FALSE,encoding='UTF-8'))))
cases<-list(list(changes=list(is_sensitive=TRUE),status='protected_field'),list(changes=list(n_available=4),status='withheld_small_complementary_cells'),list(changes=list(n_missing=1),status='withheld_small_complementary_cells'),list(changes=list(min=-999),status='needs_validation_negative_sentinel'),list(changes=list(numeric_privacy_status='withheld_constant_profile'),status='withheld_constant_profile'))
for(case in cases){invisible(publish(list(modifyList(profile('SP_PatientInfo','bmi'),case$changes))));row<-read_public_table(out,'column_profiles')[[1]];expect_equal(row$numeric_privacy_status,case$status);expect_true(all(vapply(row[c('mean','median','p25','p75')],is.null,logical(1))));if(case$status=='withheld_small_complementary_cells'){expect_equal(row$availability_privacy_status,case$status);expect_true(is.null(row$n_available)&&is.null(row$pct_available))};if(case$status=='protected_field')expect_true(row$is_sensitive)}
invisible(publish(list()));expect_equal(read_public_table(out,'column_profiles'),list())
paths<-publish(list(profile('Other','bmi')));expect_equal(read_public_table(out,'column_profiles')[[1]]$table_name,'Other')
assets<-c(unlist(paths$assets),paths$manifest);before<-tools::md5sum(assets)
failure<-try(publish(list(profile('SP_VitaleVaerdier','numericvalue',column_type=paste(rep('x',530000),collapse='')))),silent=TRUE)
expect_true(inherits(failure,'try-error'));expect_equal(tools::md5sum(assets),before)
cat('PASS R canonical vital identities, duplicates, all-format privacy and failure preservation\n')
